// ============================================================
// Rule: O365_Admin Privileges Granted
// Vendor: Microsoft 365
// Objective:
// Detect activity associated with O365_Admin Privileges Granted.
// Severity: SEV_040_HIGH
// Category: PRIVILEGE_ESCALATION
// ============================================================
// MITRE ATT&CK:
// Tactic: TA0003 - Persistence
// Technique: T1098 - Account Manipulation
// Technique: T1098.001 - Account Manipulation: Additional Cloud Credentials
// Tactic: TA0004 - Privilege Escalation
// Technique: T1098 - Account Manipulation
// Technique: T1098.003 - Account Manipulation: Additional Cloud Roles

// Fonte de dados: logs de auditoria de nuvem
dataset = cloud_audit_logs  

// Filtro para considerar apenas eventos do provedor Microsoft Azure
| filter cloud_provider = "Azure"  

// Filtro para operações relacionadas à adição de membros em funções (roles)
// Exemplo: quando um usuário recebe permissão administrativa ou outra função privilegiada
| filter operation_name_orig = "Add member to role"  

// Filtro adicional para restringir a eventos que envolvem funções de administrador
// O campo raw_log é inspecionado para identificar ocorrências contendo o termo "Administrator"
| filter raw_log ~= "Administrator"  

// Exclusão de eventos legítimos provenientes da plataforma de segurança Check Point
// Essa exclusão evita falsos positivos em integrações automatizadas conhecidas
| filter IDENTITY_INVOKED_BY_NAME != "Check Point Cloud Security Platform - Emails V2"  

// Seleção dos campos relevantes para análise
| fields operation_name_orig,        // Nome da operação (Add member to role)
         IDENTITY_NAME,              // Nome da identidade que executou a operação
         IDENTITY_ORIG,              // Origem ou entidade autenticada (ex: app, service principal, user)
         RAW_LOG,                    // Log bruto completo para referência detalhada
         REFERENCED_RESOURCE_NAME    // Nome do recurso, função ou grupo que recebeu a modificação
